const { useState } = React;

function BellIcon() {
  return (
    <svg
      aria-hidden="true"
      width="24"
      height="24"
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="2"
      strokeLinecap="round"
      strokeLinejoin="round"
      style={{ display: 'block' }}
    >
      <path d="M18 8a6 6 0 0 0-12 0c0 7-3 9-3 9h18s-3-2-3-9"></path>
      <path d="M13.73 21a2 2 0 0 1-3.46 0"></path>
    </svg>
  );
}

function App() {
  const [page, setPage] = useState('home');

  // Transactions data
  const transactions = [
    { id: 1, label: 'Rent', amount: -900 },
    { id: 2, label: 'Salary', amount: 3100 },
    { id: 3, label: 'Netflix', amount: -12 },
  ];

  // Transfer page state
  const [transferAmount, setTransferAmount] = useState('');
  const [transferTo, setTransferTo] = useState('');
  const [errors, setErrors] = useState({});
  const [transferSuccess, setTransferSuccess] = useState(false);

  function validateTransfer() {
    const newErrors = {};
    if (!transferTo.trim()) {
      newErrors.transferTo = 'Recipient is required';
    }
    if (!transferAmount.trim()) {
      newErrors.transferAmount = 'Amount is required';
    } else if (isNaN(Number(transferAmount)) || Number(transferAmount) <= 0) {
      newErrors.transferAmount = 'Enter a valid positive number';
    }
    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  }

  function handleTransferSubmit(e) {
    e.preventDefault();
    if (validateTransfer()) {
      setTransferSuccess(true);
      // Reset form after success
      setTransferAmount('');
      setTransferTo('');
      setErrors({});
    } else {
      setTransferSuccess(false);
    }
  }

  // Styles
  const styles = {
    container: {
      maxWidth: 400,
      margin: '20px auto',
      fontFamily: 'Arial, sans-serif',
      color: '#222',
      padding: '0 16px',
    },
    header: {
      display: 'flex',
      justifyContent: 'space-between',
      alignItems: 'center',
      borderBottom: '2px solid #222',
      paddingBottom: 12,
      marginBottom: 20,
    },
    title: {
      fontWeight: 'bold',
      fontSize: 24,
      userSelect: 'none',
    },
    balanceCard: {
      border: '1.5px solid #222',
      borderRadius: 8,
      padding: 16,
      marginBottom: 20,
      userSelect: 'none',
    },
    balanceLabel: {
      fontSize: 14,
      marginBottom: 8,
      color: '#555',
    },
    balanceAmount: {
      fontSize: 28,
      fontWeight: 'bold',
      letterSpacing: 1,
    },
    buttonRow: {
      display: 'flex',
      gap: 8,
      marginBottom: 20,
    },
    button: {
      flex: 1,
      border: '1.5px solid #222',
      borderRadius: 6,
      backgroundColor: 'white',
      padding: '10px 0',
      fontSize: 16,
      cursor: 'pointer',
      userSelect: 'none',
      transition: 'background-color 0.2s ease',
    },
    buttonHover: {
      backgroundColor: '#eee',
    },
    transactionsTitle: {
      fontWeight: 'bold',
      fontSize: 18,
      marginBottom: 12,
      userSelect: 'none',
    },
    transactionItem: {
      display: 'flex',
      alignItems: 'center',
      fontSize: 16,
      marginBottom: 8,
      userSelect: 'none',
    },
    transactionIcon: {
      display: 'inline-block',
      width: 12,
      height: 12,
      marginRight: 8,
      userSelect: 'none',
    },
    transferForm: {
      display: 'flex',
      flexDirection: 'column',
      gap: 12,
      maxWidth: 360,
      margin: '0 auto',
      userSelect: 'none',
    },
    label: {
      fontWeight: 'bold',
      fontSize: 14,
      marginBottom: 4,
    },
    input: {
      padding: 8,
      fontSize: 16,
      borderRadius: 4,
      border: '1.5px solid #ccc',
      outline: 'none',
      transition: 'border-color 0.2s ease',
    },
    inputError: {
      borderColor: 'red',
    },
    errorMessage: {
      color: 'red',
      fontSize: 13,
      marginTop: 2,
    },
    successMessage: {
      color: 'green',
      fontWeight: 'bold',
      fontSize: 16,
      marginTop: 12,
      textAlign: 'center',
      userSelect: 'none',
    },
    transferButtons: {
      display: 'flex',
      justifyContent: 'space-between',
      marginTop: 16,
    },
    smallButton: {
      padding: '8px 16px',
      fontSize: 16,
      borderRadius: 6,
      border: '1.5px solid #222',
      backgroundColor: 'white',
      cursor: 'pointer',
      userSelect: 'none',
      transition: 'background-color 0.2s ease',
    },
  };

  // Icon for transactions
  function TransactionIcon({ type }) {
    // type: 'rent' (up arrow), 'salary' (up arrow), 'netflix' (down arrow)
    // Rent and Netflix are negative, Salary positive
    const isPositive = type === 'salary';
    return (
      <svg
        aria-hidden="true"
        width="12"
        height="12"
        viewBox="0 0 24 24"
        fill="none"
        stroke={isPositive ? 'green' : 'red'}
        strokeWidth="3"
        strokeLinecap="round"
        strokeLinejoin="round"
        style={styles.transactionIcon}
      >
        {isPositive ? (
          <polyline points="18 15 12 9 6 15" />
        ) : (
          <polyline points="6 9 12 15 18 9" />
        )}
      </svg>
    );
  }

  if (page === 'transfer') {
    return (
      <main style={styles.container}>
        <header style={styles.header}>
          <button
            onClick={() => {
              setPage('home');
              setTransferSuccess(false);
              setErrors({});
            }}
            aria-label="Back to home"
            style={{ ...styles.smallButton, fontWeight: 'bold' }}
          >
            &larr; Home
          </button>
          <h1 style={{ ...styles.title, flexGrow: 1, textAlign: 'center' }}>Transfer</h1>
          <div style={{ width: 72 }} /> {/* placeholder for spacing */}
        </header>

        <form onSubmit={handleTransferSubmit} style={styles.transferForm} noValidate>
          <label htmlFor="transferTo" style={styles.label}>
            Recipient
          </label>
          <input
            id="transferTo"
            type="text"
            value={transferTo}
            onChange={(e) => setTransferTo(e.target.value)}
            style={{
              ...styles.input,
              ...(errors.transferTo ? styles.inputError : {}),
            }}
            aria-describedby={errors.transferTo ? 'transferTo-error' : undefined}
            aria-invalid={errors.transferTo ? 'true' : 'false'}
          />
          {errors.transferTo && (
            <p id="transferTo-error" role="alert" style={styles.errorMessage}>
              {errors.transferTo}
            </p>
          )}

          <label htmlFor="transferAmount" style={styles.label}>
            Amount
          </label>
          <input
            id="transferAmount"
            type="text"
            inputMode="decimal"
            value={transferAmount}
            onChange={(e) => setTransferAmount(e.target.value)}
            style={{
              ...styles.input,
              ...(errors.transferAmount ? styles.inputError : {}),
            }}
            aria-describedby={errors.transferAmount ? 'transferAmount-error' : undefined}
            aria-invalid={errors.transferAmount ? 'true' : 'false'}
          />
          {errors.transferAmount && (
            <p id="transferAmount-error" role="alert" style={styles.errorMessage}>
              {errors.transferAmount}
            </p>
          )}

          <div style={styles.transferButtons}>
            <button type="submit" style={styles.smallButton}>
              Send
            </button>
            <button
              type="button"
              onClick={() => {
                setPage('home');
                setTransferSuccess(false);
                setErrors({});
              }}
              style={styles.smallButton}
            >
              Cancel
            </button>
          </div>

          {transferSuccess && (
            <p role="alert" style={styles.successMessage}>
              Transfer successful!
            </p>
          )}
        </form>
      </main>
    );
  }

  // Home page
  return (
    <main style={styles.container}>
      <header style={styles.header}>
        <h1 style={styles.title}>MyBank</h1>
        <button
          aria-label="Notifications"
          style={{ background: 'none', border: 'none', cursor: 'pointer', padding: 0 }}
          onClick={() => alert('No new notifications')}
        >
          <BellIcon />
        </button>
      </header>

      <section style={styles.balanceCard} aria-label="Savings account balance">
        <p style={styles.balanceLabel}>Savings account</p>
        <p style={styles.balanceAmount}>$12,480.50</p>
      </section>

      <nav style={styles.buttonRow} aria-label="Primary actions">
        <button
          type="button"
          style={styles.button}
          onClick={() => setPage('transfer')}
          onMouseEnter={(e) => (e.currentTarget.style.backgroundColor = '#eee')}
          onMouseLeave={(e) => (e.currentTarget.style.backgroundColor = 'white')}
        >
          Transfer
        </button>
        <button
          type="button"
          style={styles.button}
          onClick={() => alert('Pay bills clicked')}
          onMouseEnter={(e) => (e.currentTarget.style.backgroundColor = '#eee')}
          onMouseLeave={(e) => (e.currentTarget.style.backgroundColor = 'white')}
        >
          Pay bills
        </button>
        <button
          type="button"
          style={styles.button}
          onClick={() => alert('Deposit clicked')}
          onMouseEnter={(e) => (e.currentTarget.style.backgroundColor = '#eee')}
          onMouseLeave={(e) => (e.currentTarget.style.backgroundColor = 'white')}
        >
          Deposit
        </button>
      </nav>

      <section aria-label="Transactions">
        <h2 style={styles.transactionsTitle}>Transactions</h2>
        <ul style={{ paddingLeft: 20, margin: 0 }}>
          {transactions.map(({ id, label, amount }) => (
            <li key={id} style={styles.transactionItem}>
              <TransactionIcon type={label.toLowerCase()} />
              <span>
                {label} {amount < 0 ? '-' : '+'}${Math.abs(amount)}
              </span>
            </li>
          ))}
        </ul>
      </section>
    </main>
  );
}

ReactDOM.createRoot(document.getElementById('root')).render(<App />);

